import java.util.HashSet;
import java.util.List;

public class Records {
    record Point(double x, double y) {
        Point {                                     // compact constructor: validate.
            if (!Double.isFinite(x) || !Double.isFinite(y))
                throw new IllegalArgumentException("coordinates must be finite");
        }
        double distanceTo(Point o) { return Math.hypot(x - o.x, y - o.y); }
    }

    record Team(String name, List<String> members) {
        Team {
            members = List.copyOf(members);          // defensive, unmodifiable copy.
        }
    }

    public static void main(String[] args) {
        Point a = new Point(0, 0), b = new Point(3, 4);
        System.out.println(a.distanceTo(b));        // 5.0
        System.out.println(new Point(3, 4).equals(b) + " " + b);   // true Point[x=3.0, y=4.0]
        var set = new HashSet<Point>(List.of(b, new Point(3, 4)));
        System.out.println(set.size());             // 1
    }
}
